import Mathlib

open Filter Finset Real

def setA : Set ℕ := {n | ∀ d ∈ Nat.digits 3 n, d ≤ 1}
def setB : Set ℕ := {n | ∀ d ∈ Nat.digits 4 n, d ≤ 1}
def setAB : Set ℕ := {n | ∃ a ∈ setA, ∃ b ∈ setB, a + b = n}

-- Helper lemma: a number with digit 2 in base 3 is not in setA
lemma has_digit_2_not_in_setA (n : ℕ) (h : 2 ∈ Nat.digits 3 n) : n ∉ setA := by
  intro hn
  rw [setA] at hn
  have := hn 2 h
  omega

theorem erdos_125 : ∃ n : ℕ, n ∉ setAB := by
  use 62
  intro h
  rw [setAB] at h
  simp only [Set.mem_setOf] at h
  obtain ⟨a, ha, b, hb, hab⟩ := h
  -- a + b = 62, a ∈ setA, b ∈ setB
  -- All elements of setB ≤ 62 are: {0, 1, 4, 5, 16, 17, 20, 21}

  have h_b_le : b ≤ 62 := by omega

  -- Case analysis on b - these are the only elements of setB ≤ 62
  interval_cases b <;> (
    try (simp [hab] at * <|> skip);
    try (have h2 : 2 ∈ Nat.digits 3 (62 - b) := by native_decide <|> skip);
    try (rw [← hab] at h2 <|> skip);
    try (exact has_digit_2_not_in_setA a h2 ha <|> skip)
  )

